// =========================================================================
// Bucket C: Scenario Coverage
// =========================================================================

// N+1 scenarios: one success + one per-transport failure + guard toggles.
// 3 single-failure scenarios (one per transport executor).
// Full failure scenarios require per-transport failure mocks (Tier 0 infra).
// 
// Guard branch: 'execute_transport_extdeps_cargo_cargo_Build_Build'.request (type: TransportRequest)
//   fed by: prepare_transport_extdeps_cargo_cargo_Build_Build.request
//   upstream is pure — needs per-node isolation (Tier 1) for full test
// 
// Guard branch: 'execute_transport_extdeps_cargo_cargo_Build_Test'.request (type: TransportRequest)
//   fed by: prepare_transport_extdeps_cargo_cargo_Build_Test.request
//   upstream is pure — needs per-node isolation (Tier 1) for full test
// 
// Guard branch: 'execute_transport_extdeps_cargo_cargo_Build_Clippy'.request (type: TransportRequest)
//   fed by: prepare_transport_extdeps_cargo_cargo_Build_Clippy.request
//   upstream is pure — needs per-node isolation (Tier 1) for full test
// 

/// Happy path: all transports succeed.
/// 
/// Proves: workflow reaches terminal outputs with all transports mocked as success.
#[test]
fn test_scenario_all_succeed() {
    if !guard_test("test_scenario_all_succeed", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("tools/build.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let log = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()), ..Default::default() }).expect("all-succeed scenario should complete");
    let entry = log.get("execute_transport_extdeps_cargo_cargo_Build_Build").expect("'execute_transport_extdeps_cargo_cargo_Build_Build' should be in log");
    assert!(entry.was_intercepted || entry.outputs.values().all(|v| matches!(v, Value::Skipped)), "'execute_transport_extdeps_cargo_cargo_Build_Build' should be intercepted or skipped in DryRun");
    let entry = log.get("execute_transport_extdeps_cargo_cargo_Build_Test").expect("'execute_transport_extdeps_cargo_cargo_Build_Test' should be in log");
    assert!(entry.was_intercepted || entry.outputs.values().all(|v| matches!(v, Value::Skipped)), "'execute_transport_extdeps_cargo_cargo_Build_Test' should be intercepted or skipped in DryRun");
    let entry = log.get("execute_transport_extdeps_cargo_cargo_Build_Clippy").expect("'execute_transport_extdeps_cargo_cargo_Build_Clippy' should be in log");
    assert!(entry.was_intercepted || entry.outputs.values().all(|v| matches!(v, Value::Skipped)), "'execute_transport_extdeps_cargo_cargo_Build_Clippy' should be intercepted or skipped in DryRun");
}

